"""Build a local animated art review using the actual native runtime poses."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[2]
ART = ROOT / 'art/enemies/compact-v1'
meta = json.loads((ART / 'metadata.json').read_text('utf-8'))
page = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>荒原回响 · 像素敌人与主角</title>
<style>body{margin:0;background:#172128;color:#e7d9b8;font:15px "Microsoft YaHei UI",sans-serif}main{max-width:1160px;margin:30px auto;padding:0 22px}h1{font-size:30px;margin-bottom:12px}p{color:#bbc5bc;line-height:1.8}button,select{background:#33434b;color:#f5dfac;border:1px solid #6a7d7c;padding:8px 16px;font:inherit;border-radius:4px}section{background:#202e35;border:1px solid #526269;padding:18px;margin:18px 0;border-radius:8px}#grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#26363d;border:1px solid #4a6064;border-radius:6px;padding:12px}.card canvas{display:block;width:100%;image-rendering:pixelated}.name{font-size:18px;font-weight:bold;color:#f5d29b}.note{font-size:12px;color:#acbbb3;line-height:1.7}#lineup{width:100%;image-rendering:pixelated}a{color:#e9b778}@media(max-width:800px){#grid{grid-template-columns:repeat(2,1fr)}}</style>
<main><h1>荒原回响 · 主角与八类敌人</h1><p>沿用已认可巡线者的紧凑像素语言。八类敌人各有八张绘制步态，按各自移动速度播放；主角复用分层枪械、手套和袖口。此页供美术对照，实战素材同时接入主游戏。</p>
<section><button id="pause">暂停</button> <label>朝向 <select id="facing"><option value="1">向右</option><option value="-1">向左</option></select></label> <label>状态 <select id="motion"><option value="walk">行走／奔跑</option><option value="idle">静止</option></select></label> <span id="status">加载中</span></section>
<section><h2>同一游戏尺寸对照</h2><canvas id="lineup" width="1120" height="235"></canvas><p class="note">主角、普通感染者与首领采用同一原生像素密度。首领的实际体积更大；本页放大展示不改变游戏碰撞半径。</p></section>
<div id="grid"></div><section><a href="../../characters/ranger/modular-grips-v3/review.html">查看原主角分层样板</a> · <a href="../../../docs/compact-enemies-live-plan-2026-10-28.md">本轮范围与验收</a><p class="note">生成原画、导入参数、可编辑Aseprite、无损运行图与提示词均保留。新敌人整体观感仍需你的实际试玩反馈；其他英雄和服饰的独立像素身体尚未制作。</p></section></main>
<script src="../../../src/shared/compact-ranger-motion.js"></script><script src="../../../src/shared/modular-grip-compositor.js"></script><script src="../../characters/ranger/modular-grips-v3/modular-data.js"></script>
<script>const DATA=__DATA__;const speeds={drifter:45,runner:104,spitter:42,brute:31,screecher:59,crawler:83,warden:38,iron_colossus:29};let paused=false,time=0,last=0;const images={},cards={};
const load=url=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=url;});
document.querySelector('#pause').onclick=()=>{paused=!paused;document.querySelector('#pause').textContent=paused?'继续':'暂停'};
function enemy(ctx,id,x,y,scale){const d=DATA.enemies[id],moving=document.querySelector('#motion').value==='walk',frame=moving?Math.floor(time*speeds[id]/d.stride*8)%8:d.idleFrame;ctx.save();ctx.imageSmoothingEnabled=false;ctx.translate(x,y);ctx.scale(scale*Number(document.querySelector('#facing').value),scale);ctx.drawImage(images[id],frame*d.canvas,0,d.canvas,d.canvas,-d.root[0],-d.root[1],d.canvas,d.canvas);ctx.restore();}
function base(ctx,w,h){ctx.fillStyle='#26363d';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#576767';ctx.beginPath();ctx.moveTo(0,h-35);ctx.lineTo(w,h-35);ctx.stroke();}
let hero,body,grip;
function render(){const c=document.querySelector('#lineup'),ctx=c.getContext('2d');base(ctx,c.width,c.height);hero.x=55;hero.y=180;hero.walking=document.querySelector('#motion').value==='walk';hero.phase=time*178/68%1;CompactRangerMotion.setAimAngle(hero,Number(document.querySelector('#facing').value)>0?-.1:Math.PI+.1);CompactRangerMotion.draw(ctx,hero,{body,weapon:grip.image},{drawShadow:false,drawTargets:false,drawProjectiles:false,drawImpacts:false,drawFlash:false});ctx.fillStyle='#f5d29b';ctx.font='14px Microsoft YaHei';ctx.fillText('巡线者',25,220);let i=0;for(const [id,d]of Object.entries(DATA.enemies)){const x=155+i*123;enemy(ctx,id,x,180,1.5);ctx.fillStyle='#e2cfaa';ctx.fillText(d.name,x-28,220);const card=cards[id],cc=card.getContext('2d');base(cc,card.width,card.height);enemy(cc,id,card.width/2,card.height-35,Math.min(3,(card.height-45)/d.referenceHeight));i++;}}
(async()=>{for(const [id,d]of Object.entries(DATA.enemies)){images[id]=await load(id+'-atlas.png');const card=document.createElement('div');card.className='card';card.innerHTML='<div class="name">'+d.name+'</div><canvas width="240" height="210"></canvas><div class="note">'+d.silhouette+' · 8帧</div>';document.querySelector('#grid').append(card);cards[id]=card.querySelector('canvas');}const D=MODULAR_GRIP_DATA,basePath='../../characters/ranger/modular-grips-v3/';body=await load(basePath+D.characters[D.defaultCharacter].bodyAtlas);const textures={};for(const id of ['weapon.scrap_pistol','hands.ranger-cloth','cuffs.ranger-coat'])textures[id]=await load(basePath+D.assets[id].path);hero=CompactRangerMotion.createState({x:55,y:180,pixelScale:1.5,weapons:ModularGrip.definitionsForCharacter(D),weaponId:'scrap_pistol',body:D.characters[D.defaultCharacter].body});const cache=ModularGrip.createCache(D,textures);grip=cache.apply(hero,'scrap_pistol');window.enemyReview={ready:true,render,images,DATA,freeze(){paused=true;},setTime(value){time=value;render();}};document.querySelector('#status').textContent='全部就绪 · 原生素材';function tick(now){if(last&&!paused)time+=Math.min(.05,(now-last)/1000);last=now;render();requestAnimationFrame(tick)}requestAnimationFrame(tick);})().catch(error=>{document.querySelector('#status').textContent=error.message;throw error;});</script></html>'''
page = page.replace('__DATA__', json.dumps(meta, ensure_ascii=False))
(ART / 'review.html').write_text(page, encoding='utf-8')
print(ART / 'review.html')
